/** 订阅播放进度（~2Hz）。回退订函数。 */
export function onVideoProgress(handler) {
    const api = bridge();
    if (!api?.video?.subscribe || !api?.events?.on)
        return () => { };
    let off = () => { };
    try {
        off = api.events.on('video.progress', handler) || (() => { });
    }
    catch {
        return () => { };
    }
    fireAndForget(() => api.video.subscribe());
    return () => {
        fireAndForget(() => api.video.unsubscribe?.());
        try {
            off();
